#[cfg(test)]
#[path = "coaching_relationships_access_tests.rs"]
mod access_tests;

#[cfg(test)]
mod tests {
    use super::*;

    fn create_test_relationship(coach_id: Id, coachee_id: Id) -> Model {
        relationship_of(Kind::Coaching, coach_id, coachee_id)
    }

    fn relationship_of(kind: Kind, coach_id: Id, coachee_id: Id) -> Model {
        let now = chrono::Utc::now().fixed_offset();
        Model {
            id: Id::new_v4(),
            organization_id: Id::new_v4(),
            coach_id,
            coachee_id,
            kind,
            slug: "test-slug".to_string(),
            created_at: now,
            updated_at: now,
        }
    }

    #[test]
    fn includes_user_returns_true_for_coach() {
        let coach_id = Id::new_v4();
        let coachee_id = Id::new_v4();
        let relationship = create_test_relationship(coach_id, coachee_id);

        assert!(relationship.includes_user(coach_id));
    }

    #[test]
    fn includes_user_returns_true_for_coachee() {
        let coach_id = Id::new_v4();
        let coachee_id = Id::new_v4();
        let relationship = create_test_relationship(coach_id, coachee_id);

        assert!(relationship.includes_user(coachee_id));
    }

    #[test]
    fn a_request_cannot_choose_the_kind() {
        let body = serde_json::json!({
            "coach_id": Id::new_v4(),
            "coachee_id": Id::new_v4(),
            "kind": "colleague",
        });
        let relationship: Model = serde_json::from_value(body).expect("deserializes");
        assert_eq!(relationship.kind, Kind::Coaching);
    }

    #[test]
    fn includes_user_returns_false_for_unrelated_user() {
        let coach_id = Id::new_v4();
        let coachee_id = Id::new_v4();
        let other_user_id = Id::new_v4();
        let relationship = create_test_relationship(coach_id, coachee_id);

        assert!(!relationship.includes_user(other_user_id));
    }

    #[test]
    fn a_coaching_relationship_seats_and_empowers_only_its_coach() {
        let (coach, coachee, stranger) = (Id::new_v4(), Id::new_v4(), Id::new_v4());
        let relationship = relationship_of(Kind::Coaching, coach, coachee);

        assert_eq!(relationship.seat(coach), Some(Seat::CoachId));
        assert_eq!(
            relationship.role(coach),
            Some(coaching_relationship_kind::Role::Coach)
        );
        assert!(relationship.can_schedule_sessions(coach));

        assert_eq!(relationship.seat(coachee), Some(Seat::CoacheeId));
        assert_eq!(
            relationship.role(coachee),
            Some(coaching_relationship_kind::Role::Coachee)
        );
        assert!(!relationship.can_schedule_sessions(coachee));
        assert!(relationship.sees_all_actions(coach));
        assert!(!relationship.sees_all_actions(coachee));

        assert_eq!(relationship.seat(stranger), None);
        assert_eq!(relationship.role(stranger), None);
        assert!(!relationship.can_schedule_sessions(stranger));
        assert!(!relationship.sees_all_actions(stranger));
    }

    #[test]
    fn a_self_coaching_relationship_seats_its_one_user_as_coach() {
        let user = Id::new_v4();
        let relationship = relationship_of(Kind::Coaching, user, user);

        assert_eq!(relationship.seat(user), Some(Seat::CoachId));
        assert_eq!(
            relationship.role(user),
            Some(coaching_relationship_kind::Role::Coach)
        );
        assert!(relationship.can_schedule_sessions(user));
    }

    #[test]
    fn a_colleague_relationship_empowers_both_participants() {
        let (first, second, stranger) = (Id::new_v4(), Id::new_v4(), Id::new_v4());
        let relationship = relationship_of(Kind::Colleague, first, second);

        for (user, seat) in [(first, Seat::CoachId), (second, Seat::CoacheeId)] {
            assert_eq!(relationship.seat(user), Some(seat));
            assert_eq!(
                relationship.role(user),
                Some(coaching_relationship_kind::Role::Colleague)
            );
            assert!(relationship.can_schedule_sessions(user));
            assert!(relationship.sees_all_actions(user));
        }
        assert_eq!(relationship.seat(stranger), None);
        assert_eq!(relationship.role(stranger), None);
        assert!(!relationship.can_schedule_sessions(stranger));
        assert!(!relationship.sees_all_actions(stranger));
    }

    #[test]
    fn coaching_authority_is_still_being_the_coach() {
        let (coach, coachee, stranger) = (Id::new_v4(), Id::new_v4(), Id::new_v4());
        let pair = relationship_of(Kind::Coaching, coach, coachee);
        let solo = relationship_of(Kind::Coaching, coach, coach);

        for (relationship, user) in [
            (&pair, coach),
            (&pair, coachee),
            (&pair, stranger),
            (&solo, coach),
        ] {
            assert_eq!(
                relationship.can_schedule_sessions(user),
                user == relationship.coach_id,
                "{user}"
            );
        }
    }

    #[test]
    fn a_coaching_sessions_owner_is_its_coach_whoever_schedules() {
        let (coach, coachee) = (Id::new_v4(), Id::new_v4());
        let relationship = relationship_of(Kind::Coaching, coach, coachee);

        for scheduler in [coach, coachee] {
            assert_eq!(relationship.schedule_owner_id(scheduler), coach);
            assert_eq!(relationship.meeting_account_ids(scheduler), [coach]);
        }
    }

    #[test]
    fn a_colleague_sessions_owner_is_its_scheduler_then_the_other_colleague() {
        let (first, second) = (Id::new_v4(), Id::new_v4());
        let relationship = relationship_of(Kind::Colleague, first, second);

        for (scheduler, other) in [(first, second), (second, first)] {
            assert_eq!(relationship.schedule_owner_id(scheduler), scheduler);
            assert_eq!(
                relationship.meeting_account_ids(scheduler),
                [scheduler, other]
            );
        }
    }
}
